// Extraer el body — n8n v2 lo pone en .body, v1 en la raíz
const raw = $input.first().json;
const body = raw.body ?? raw;

const message    = String(body.message   ?? '').trim();
const history    = Array.isArray(body.history) ? body.history : [];
const manual     = String(body.manual    ?? '');
const userRole   = String(body.user_role ?? 'employee');
const page       = String(body.page      ?? '');

if (!message) throw new Error('El campo message está vacío');

const roleLabel = userRole === 'admin' || userRole === 'manager'
  ? 'administrador o manager'
  : 'empleado';

const systemPrompt = [
  'Eres el asistente de ayuda de TimeTrack, una plataforma de control horario.',
  'Responde siempre en español. Sé conciso, directo y amable.',
  'Máximo 3-4 párrafos por respuesta. Usa listas cuando ayude a la claridad.',
  'Solo responde preguntas sobre el uso de la aplicación TimeTrack.',
  'Si la pregunta no tiene relación con la app, indica amablemente que solo puedes ayudar con TimeTrack.',
  '',
  `El usuario es un ${roleLabel}.`,
  page ? `Está en la pantalla: ${page}.` : '',
  '',
  '--- MANUAL DE LA APLICACIÓN ---',
  manual,
  '--- FIN DEL MANUAL ---',
].filter(l => l !== null).join('\n');

// Construir el array de mensajes respetando el historial de conversación
const messages = [
  ...history
    .filter(h => h.role === 'user' || h.role === 'assistant')
    .slice(-10)  // máx 10 turnos de historial
    .map(h => ({ role: h.role, content: String(h.content) })),
  { role: 'user', content: message },
];

return [{
  json: {
    anthropicRequest: {
      model: 'claude-sonnet-4-5',
      max_tokens: 1024,
      system: systemPrompt,
      messages,
    }
  }
}];

const response = $input.first().json;

// Extraer el texto de la respuesta de Anthropic
const answer = response?.content?.[0]?.text
  ?? response?.error?.message
  ?? 'Lo siento, no pude procesar tu pregunta. Por favor inténtalo de nuevo.';

return [{ json: { answer } }];
